selected.compute:
rows = read('/input/options')
result = None
for count in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(rows, count):
        proposal = [row['id'] for row in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

selected.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        result = existing
    else:
        result = None
if result is None:
    status('report')
else:
    delivery = receipt('report')
    if delivery == 'success':
        pass
    elif delivery == 'unknown':
        status('report')
    elif delivery == 'failure' or delivery == 'unattempted':
        send('report', 'team', result)
if not exists('/output/selection') and result is not None:
    write('/output/selection', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
